import{_ as n,l,o as e,c as o,v as t,p as s,x as r,d,i as E,S as A}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"双重差分","description":"","frontmatter":{"title":"双重差分","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/difference-in-differences.md","filePath":"econ/difference-in-differences.md","lastUpdated":1789023840000}'),p={name:"econ/difference-in-differences.md"};function h(_,a,c,f,m,B){const i=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="双重差分" tabindex="-1">双重差分 <a class="header-anchor" href="#双重差分" aria-label="Permalink to &quot;双重差分&quot;">​</a></h1><div class="epigraph"><p>处理组与对照组的差分还含组间基线差；时间上的差分还含共同趋势。再差一次，剩下的是处理——若平行趋势成立。</p><footer>—— 据 Ashenfelter 培训项目；Card and Krueger, Minimum Wages and Employment: A Case Study of the Fast-Food Industry in New Jersey and Pennsylvania, AER 1994</footer></div><p><a href="/econ/gmm-econ">上一课</a>把矩条件与最优权重收完。本课换设计：政策在部分群体、部分时间发生，用双重差分（DiD）识别 ATT。交错采纳的加权病下一课再拆；本课先钉两期两组与平行趋势。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>州 \\(A\\) 在 \\(t=1\\) 提高最低工资，州 \\(B\\) 不变。单差「\\(A\\) 前后」含一切时间冲击；单差「\\(A\\) 对 \\(B\\)」含一切州特质。Card–Krueger 的逻辑是：若没有政策时两边就业的<strong>变化</strong>相同（平行趋势），则</p> \\[\\mathrm{ATT}=\\bigl(\\mathbb{E}[Y_{A1}]-\\mathbb{E}[Y_{A0}]\\bigr)-\\bigl(\\mathbb{E}[Y_{B1}]-\\mathbb{E}[Y_{B0}]\\bigr). \\]<p>缺口不是再估一个弹性发表数，而是：平行趋势是对反事实 \\(Y(0)\\) 的陈述，预趋势可以证伪它，不能证实它。回归写法 \\(Y_{it}=\\alpha_i+\\lambda_t+\\beta D_{it}+u_{it}\\) 在两期两组等于上述差中差；多期仍要平行趋势，且立刻撞上交错加权——留给下一课。</p><p><span class="marginnote">Ashenfelter 低谷：培训前处理组暂时变差，于是「培训效果」含均值回复。预趋势检验要看的是政策前，不是把政策后的均值回复叫效应。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两期：饱和回归与细胞均值等价。多期、同时处理：双向固定效应（TWFE）在同质效应下仍是 DiD。控制：可加的组效应、时间效应；不可把处理当中介的坏控制放进来。标准误：州层面政策要在州上聚类——Bertrand、Duflo 与 Mullainathan（2004）表明忽略序列相关会让 DiD 的 \\(t\\) 膨胀。</p>',10)),(e(),s(A,null,{default:r(()=>[E(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E5%B9%B3%E8%A1%8C%E8%B6%8B%E5%8A%BF%3A%20%E5%8F%8D%E4%BA%8B%E5%AE%9E%20Y(0)%20%E5%90%8C%E8%B5%B0%22%5D%20--%3E%20DID%5B%22%E5%B7%AE%E4%B8%AD%E5%B7%AE%20%3D%20ATT%22%5D%0A%20%20PRET%5B%22%E9%A2%84%E8%B6%8B%E5%8A%BF%22%5D%20--%3E%20FALS%5B%22%E5%8F%AF%E8%AF%81%E4%BC%AA%2C%20%E4%B8%8D%E5%8F%AF%E8%AF%81%E5%AE%9E%22%5D%0A%20%20TWFE%5B%22TWFE%22%5D%20--%3E%20DID%0A%20%20STAG%5B%22%E4%BA%A4%E9%94%99%E9%87%87%E7%BA%B3%22%5D%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%8A%A0%E6%9D%83%E5%8F%AF%E8%B4%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>事件研究图：政策前系数应在零附近（给定精度），政策后给动态 ATT。这是设计的展示，不是新的识别理论。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是用对照组的时间变化当处理组反事实。潜在结果：\\(Y_{it}(0)=\\alpha_i+\\lambda_t+\\varepsilon_{it}\\) 可加，于是平行。处理效应若也是可加常数，\\(\\beta\\) 即 ATT。效应随时间变，事件研究估动态；效应随组变且采纳交错，TWFE 可能把已经处理的组当成对照——下一课 Goodman-Bacon。</p><p>与 IV：有时政策工具化处理强度（Bartik、资格规则），DiD 与 IV 会叠。本课纯设计是「谁在何时被处理」可观测，\\(D_{it}\\) 本身当回归元，外生来自平行趋势而不是排除约束。</p><p><span class="marginnote">合成控制下一课序后段用加权对照构造反事实，适合「一个处理单位、没有自然对照」。DiD 适合多单位、共同时间冲击可减。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Card–Krueger 的就业符号当成最低工资辩论的终审。不处理交错 DiD 的负权重。溢出（处理州顾客跑到对照州）破坏 SUTVA。量化栏的事件研究围绕公告日与价格，对象是资产回报，不在此重写。下一课专门拆 TWFE 在多期交错下估的是什么。</p><p>后课默认：两期两组 DiD = 平行趋势下的 ATT；预趋势是证伪工具。多期交错不要默认 TWFE 等于「平均 DiD」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>差中差减掉组间水平与共同时间；留下处理，若平行趋势真。</li><li>预趋势可证伪、不可证实；Ashenfelter 低谷是均值回复。</li><li>政策在群层发生则群层聚类（Bertrand–Duflo–Mullainathan）。</li><li>交错采纳的 TWFE 加权问题下一课。</li><li>出处：Card and Krueger, <em>AER</em> 1994；Ashenfelter 培训；Bertrand, Duflo and Mullainathan, <em>QJE</em> 2004。</li></ul>',10))])}const u=n(p,[["render",h]]);export{T as __pageData,u as default};
